/**
 * PricingTab.jsx
 * Option pricing model with Greeks calculation
 */

import React, { useState } from 'react';
import { Calculator, Info } from 'lucide-react';
import { useOptionPricing } from '../../../hooks/useOptionPricing';
import { trackFinancialCalculation } from '../../../hooks/usePageTracking';

const PricingTab = () => {
  const {
    parameters,
    updateParameter,
    results,
    validation,
    calculateOptionPrice,
    calculateGreeks
  } = useOptionPricing();

  const [showGreeks, setShowGreeks] = useState(true);

  // Format number for display
  const formatNumber = (num, decimals = 2) => {
    if (isNaN(num) || !isFinite(num)) return 'N/A';
    return num.toFixed(decimals);
  };

  // Safe getter for Greeks with defaults
  const getGreek = (greekName, fallback = 0) => {
    return results?.[greekName] ?? fallback;
  };

  // Handle calculation and track analytics
  const handleCalculation = () => {
    if (validation.isValid) {
      // Trigger calculation by updating parameters (this should recalculate automatically)
      trackFinancialCalculation('option_pricing', {
        underlying_price: parameters.S,
        strike_price: parameters.K,
        time_to_expiry: parameters.T,
        risk_free_rate: parameters.r,
        volatility: parameters.sigma,
        dividend_yield: parameters.q,
        call_price: results.callPrice,
        put_price: results.putPrice
      });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 mb-6">
        <Calculator className="w-6 h-6 text-red-600" />
        <h2 className="text-2xl font-semibold">Option Pricing</h2>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Input Parameters */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold mb-4">Market Parameters</h3>

          <div>
            <label className="block text-sm font-medium mb-2">
              Underlying Price (S) <span className="text-red-500">*</span>
            </label>
            <input
              type="number"
              value={parameters.S}
              onChange={(e) => updateParameter('S', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="100"
              step="0.01"
            />
            {validation.errors.S && (
              <p className="text-sm text-red-500 mt-1">{validation.errors.S}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Strike Price (K) <span className="text-red-500">*</span>
            </label>
            <input
              type="number"
              value={parameters.K}
              onChange={(e) => updateParameter('K', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="100"
              step="0.01"
            />
            {validation.errors.K && (
              <p className="text-sm text-red-500 mt-1">{validation.errors.K}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Time to Expiry (T) - Years <span className="text-red-500">*</span>
            </label>
            <input
              type="number"
              value={parameters.T}
              onChange={(e) => updateParameter('T', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="0.25"
              step="0.01"
              min="0"
            />
            {validation.errors.T && (
              <p className="text-sm text-red-500 mt-1">{validation.errors.T}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Risk-Free Rate (r) - % <span className="text-red-500">*</span>
            </label>
            <input
              type="number"
              value={parameters.r * 100}
              onChange={(e) => updateParameter('r', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="5"
              step="0.01"
            />
            {validation.errors.r && (
              <p className="text-sm text-red-500 mt-1">{validation.errors.r}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Volatility (σ) - % <span className="text-red-500">*</span>
            </label>
            <input
              type="number"
              value={parameters.sigma * 100}
              onChange={(e) => updateParameter('sigma', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="20"
              step="0.01"
            />
            {validation.errors.sigma && (
              <p className="text-sm text-red-500 mt-1">{validation.errors.sigma}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Dividend Yield (q) - %
            </label>
            <input
              type="number"
              value={parameters.q * 100}
              onChange={(e) => updateParameter('q', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="0"
              step="0.01"
            />
          </div>

          <button
            onClick={handleCalculation}
            disabled={!validation.isValid}
            className="w-full bg-red-600 hover:bg-red-700 disabled:bg-gray-400 text-white py-2 px-4 rounded-lg transition-colors"
          >
            Calculate Option Prices
          </button>
        </div>

        {/* Results */}
        <div className="space-y-6">
          {/* Option Prices */}
          <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-lg">
            <h3 className="text-lg font-semibold mb-4">Option Prices</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="text-center p-4 bg-green-100 dark:bg-green-900/30 rounded-lg">
                <p className="text-sm text-gray-600 dark:text-gray-400">Call Price</p>
                <p className="text-2xl font-bold text-green-600 dark:text-green-400">
                  ${formatNumber(results.callPrice)}
                </p>
              </div>
              <div className="text-center p-4 bg-red-100 dark:bg-red-900/30 rounded-lg">
                <p className="text-sm text-gray-600 dark:text-gray-400">Put Price</p>
                <p className="text-2xl font-bold text-red-600 dark:text-red-400">
                  ${formatNumber(results.putPrice)}
                </p>
              </div>
            </div>
          </div>

          {/* Greeks Spreadsheet */}
          {showGreeks && (
            <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-lg">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold">Greeks</h3>
                <button
                  onClick={() => setShowGreeks(!showGreeks)}
                  className="text-red-600 hover:text-red-700"
                >
                  <Info className="w-4 h-4" />
                </button>
              </div>

              {/* Spreadsheet-style Greeks table */}
              <div className="bg-white dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-700 overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 dark:bg-gray-700">
                    <tr>
                      <th className="px-3 py-2 text-left font-medium text-gray-700 dark:text-gray-300">Greek</th>
                      <th className="px-3 py-2 text-center font-medium text-gray-700 dark:text-gray-300">Call</th>
                      <th className="px-3 py-2 text-center font-medium text-gray-700 dark:text-gray-300">Put</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-600">
                    <tr className="hover:bg-gray-50 dark:hover:bg-gray-800">
                      <td className="px-3 py-2 font-medium text-gray-900 dark:text-gray-100">Delta (Δ)</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('callDelta'), 3)}</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('putDelta'), 3)}</td>
                    </tr>
                    <tr className="hover:bg-gray-50 dark:hover:bg-gray-800">
                      <td className="px-3 py-2 font-medium text-gray-900 dark:text-gray-100">Gamma (Γ)</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('gamma'), 3)}</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('gamma'), 3)}</td>
                    </tr>
                    <tr className="hover:bg-gray-50 dark:hover:bg-gray-800">
                      <td className="px-3 py-2 font-medium text-gray-900 dark:text-gray-100">Theta (Θ)</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('callTheta'), 3)}</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('putTheta'), 3)}</td>
                    </tr>
                    <tr className="hover:bg-gray-50 dark:hover:bg-gray-800">
                      <td className="px-3 py-2 font-medium text-gray-900 dark:text-gray-100">Vega (ν)</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('vega'), 3)}</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('vega'), 3)}</td>
                    </tr>
                    <tr className="hover:bg-gray-50 dark:hover:bg-gray-800">
                      <td className="px-3 py-2 font-medium text-gray-900 dark:text-gray-100">Rho (ρ)</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('callRho'), 3)}</td>
                      <td className="px-3 py-2 text-center font-mono">{formatNumber(getGreek('putRho'), 3)}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Validation Message */}
          {!validation.isValid && (
            <div className="bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-800 p-4 rounded-lg">
              <p className="text-yellow-800 dark:text-yellow-200 text-sm">
                Please fill in all required parameters to calculate option prices.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PricingTab;
